&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;Per Diem - 2x a month 7a-7p with weekends&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal0&quot;&gt;Responsibilities:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Obtain and record patient vital signs, height, and weight accurately in the electronic medical record (Athena Health).&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Take medical histories and perform screening procedures as directed.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Assist with basic wound care,&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;phlebotomy&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; EKGs&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; and splinting procedures (with training)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Perform front desk duties, including answering phones, patient check-in/out, and documentation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prepare, process, and run lab tests, including specimen collection, labelling, and handling in accordance with Sollis Health protocols.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Communicate observations and patient concerns clearly to the healthcare team.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Support emergency care efforts as a team member under supervision.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Provide a welcoming environment and exceptional customer service—answering patient questions and easing concerns.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Help with patient mobility and transfers, using proper body mechanics.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Maintain cleanliness, order, and compliance with all health and safety protocols.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Perform related duties as requested&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal0&quot;&gt;Experience &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal0&quot;&gt;We believe extraordinary people come from a variety of backgrounds, but ideally, we would expect that you have:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;High school diploma or equivalent, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;required&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Completion of a &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;National &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Medical Assistant training program&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Certified Medical Assistant &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;or&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; Phlebotomy &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Technician&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; strongly&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; preferred&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;BLS &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;or CPR certificate &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;required&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Range: $20-$30 per hour&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;This is the anticipated rate/range Sollis Health reasonably expects to pay candidates for this position in NYC. Sollis is a multi-state employer and this rate/range may not reflect the pay for positions that are performed solely in localities outside of this location. Actual pay is dependent on several factors that may include but are not limited to years of experience within the job, years of experience within the required industry, location, education, etc.&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Sollis Health&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;p&gt;Sollis Health is the first and only medical membership that’s on-demand 24/7, 365. We live up to the concierge promise: with just one call, our members experience unparalleled care and follow-up on their schedule and their terms.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our members never wonder if it’s a “real” emergency. They simply call Sollis for immediate access to ER-trained medical teams, on-site labs and imaging, expedited specialist appointments, and care navigation that’s all under one roof. With unlimited 24/7 virtual and in-person support from locations in Manhattan, the Hamptons, Los Angeles, South Florida, and San Francisco, Sollis puts our members in first class by handling all medical issues—big or small—with expert concierge care anytime, anywhere.&amp;nbsp;&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;

